#include <iostream>
#include <cstdlib>
#include <vector>

int main() {
    // 1. C-style dynamic memory allocation with calloc & realloc
    size_t count = 3;
    int* c_arr = static_cast<int*>(std::calloc(count, sizeof(int)));
    if (!c_arr) {
        return 1;
    }

    c_arr[0] = 10;
    c_arr[1] = 20;
    c_arr[2] = 30;

    size_t new_count = 5;
    int* temp = static_cast<int*>(std::realloc(c_arr, new_count * sizeof(int)));
    if (temp) {
        c_arr = temp;
        c_arr[3] = 40;
        c_arr[4] = 50;
    } else {
        std::free(c_arr);
        return 1;
    }

    std::cout << "C-style array:";
    for (size_t i = 0; i < new_count; ++i) {
        std::cout << " " << c_arr[i];
    }
    std::cout << "\n";
    std::free(c_arr);

    // 2. Modern C++17 RAII alternative using std::vector
    std::vector<int> v(count, 0);
    v[0] = 10;
    v[1] = 20;
    v[2] = 30;
    v.resize(new_count, 0);
    v[3] = 40;
    v[4] = 50;

    std::cout << "C++17 vector:";
    for (int val : v) {
        std::cout << " " << val;
    }
    std::cout << "\n";

    return 0;
}

