#include <iostream>
#include <cstdlib>

void cleanup() {
    std::cout << "[atexit] Cleanup executed.\n";
}

// C++17 fold expression replacing legacy C va_list
template <typename... Args>
auto calculateProduct(Args... args) {
    return (args * ...);
}

int main() {
    // 1. Register termination callback
    std::atexit(cleanup);

    // 2. Explicit literal suffixes (Section 14.7)
    unsigned long ul_val = 50000UL;
    float f_val = 2.5f;
    std::cout << "Literals: " << ul_val << " and " << f_val << "\n";

    // 3. Modern variadic calculation (Section 14.3)
    std::cout << "Product: " << calculateProduct(2, 3, 4) << "\n";

    std::cout << "Exiting main...\n";
    return EXIT_SUCCESS;
}
